function isMealSaveAttempt(value:unknown):value is MealSaveAttempt{
 if(!value||typeof value!=="object")return false;
 const attempt=value as Partial<MealSaveAttempt>;
 if(typeof attempt.key!=="string"||!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(attempt.key)||
    typeof attempt.localDate!=="string"||!/^\d{4}-\d{2}-\d{2}$/.test(attempt.localDate)||
    typeof attempt.loggedAt!=="string"||!Number.isFinite(Date.parse(attempt.loggedAt))||
    typeof attempt.mealType!=="string"||!["manual","text","photo"].includes(String(attempt.source))||
    typeof attempt.original!=="string"||!Array.isArray(attempt.items)||attempt.items.length<1||attempt.items.length>30)return false;
 const expected=JSON.stringify({date:attempt.localDate,mealType:attempt.mealType,source:attempt.source,original:attempt.original});
 return attempt.signature===expected&&attempt.items.every(item=>Boolean(item)&&typeof item.foodId==="string"&&
   typeof item.grams==="number"&&Number.isFinite(item.grams)&&item.grams>0&&item.grams<=10000&&
   typeof item.portionEstimated==="boolean");
}
