function dayLabel(d:string){return new Date(d+"T12:00:00+05:30").toLocaleDateString("en-IN",{weekday:"short",day:"numeric",month:"short",timeZone:"Asia/Kolkata"});}
function clock(s:string){return new Date(s).toLocaleTimeString("en-IN",{hour:"2-digit",minute:"2-digit",timeZone:"Asia/Kolkata"});}
function Bar({value,target}:{value:number;target:number|null}){return <div className="bar"><span style={{width:Math.min(100,Math.max(0,target&&target>0?100*value/target:0))+"%"}}/></div>;}
function HistoryLineChart({title,unit,points}:{title:string;unit:string;points:Array<{date:string;value:number|null}>}){const available=points.filter(p=>typeof p.value==="number"&&Number.isFinite(p.value));if(!available.length)return <section className="chart-panel"><div className="panel-title">{title}</div><div className="empty-state" style={{marginTop:10}}><strong>No recorded values in this period</strong><p>Only explicitly saved values appear here; missing days are left blank.</p></div></section>;const values=available.map(p=>p.value as number),min=Math.min(...values),max=Math.max(...values),range=max-min||Math.max(1,Math.abs(max)*.1);const x=(i:number)=>points.length<=1?300:20+i*560/(points.length-1);const y=(v:number)=>145-(v-min)/range*110;const segments:Array<Array<{x:number;y:number}>>=[];let segment:Array<{x:number;y:number}>=[];points.forEach((p,i)=>{if(typeof p.value==="number"&&Number.isFinite(p.value)){segment.push({x:x(i),y:y(p.value)});}else if(segment.length){segments.push(segment);segment=[];}});if(segment.length)segments.push(segment);const labels=[points[0],points[Math.floor((points.length-1)/2)],points[points.length-1]].filter((p,i,a)=>p&&a.findIndex(q=>q?.date===p.date)===i);return <section className="chart-panel"><div className="panel-header"><div><h3 className="panel-title">{title}</h3><p className="panel-subtitle">{available.length} recorded value(s) · range {fmt(min,1)}–{fmt(max,1)} {unit}</p></div></div><svg className="history-chart" viewBox="0 0 600 170" role="img" aria-label={title+" over time, vertical unit "+unit}><line x1="20" y1="35" x2="580" y2="35" className="chart-gridline"/><line x1="20" y1="90" x2="580" y2="90" className="chart-gridline"/><line x1="20" y1="145" x2="580" y2="145" className="chart-gridline"/>{segments.map((seg,i)=><polyline key={i} points={seg.map(p=>p.x+","+p.y).join(" ")} className="chart-line"/>) }{points.map((p,i)=>typeof p.value==="number"&&Number.isFinite(p.value)?<circle key={p.date+"-"+i} cx={x(i)} cy={y(p.value)} r="3.5" className="chart-point"><title>{p.date}: {fmt(p.value,1)} {unit}</title></circle>:null)}</svg><div className="chart-date-labels">{labels.map((p)=><span key={p!.date}>{p!.date}</span>)}</div><div className="chart-summary"><span>Low: {fmt(min,1)} {unit}</span><span>High: {fmt(max,1)} {unit}</span><span>Entries: {available.length}</span></div></section>;}
