 async function saveLabelFood(proposal:Row){
 const name=String(proposal.productName||"").trim();
 if(name.length<2)throw new Error("Gemini could not read a product name from this label. Try a clearer photo.");
 const per100g:Record<string,number>={};
 for(const item of proposal.nutrients||[])if(item.key&&NUTRIENT_BY_KEY[item.key]&&!NUTRIENT_BY_KEY[item.key].qualitative&&typeof item.per100gValue==="number"&&Number.isFinite(item.per100gValue)&&item.per100gValue>=0)per100g[item.key]=item.per100gValue;
 if(!Object.keys(per100g).length)throw new Error("Gemini could not read usable nutrient values from this label. Try a sharper photo.");
 await api("/api/foods","POST",{name,aliases:[],preparation:"Packaged product; nutrition values automatically transcribed from a label; values stored per 100 g",per100g,sourceNote:"AI-transcribed nutrition-label values from a photo on "+new Date().toISOString()+". Converted to per 100 g only where the serving mass was available. Provisional and not independently verified."});
 setMessage("Nutrition label extracted and saved automatically. AI-transcribed values are provisional estimates.");
 setPhoto(null);setPhotoNote("");
 await refresh();
}
async function analyzeText(){
  const description=text.trim();
  if(!description){setError("Describe a meal first.");return;}
  setBusy(true);setError("");setMessage("");setMealStatus("Sending your description to Gemini for food recognition and nutrient estimation…");
  try{
   const r=await fetch("/api/analyze",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({text:description})});
   const p=await r.json();
   if(!r.ok){throw new Error(p.error||"Food analysis failed. Check Gemini provider setup and retry.");}
   const candidates=Array.isArray(p.candidates)?p.candidates as Row[]:[];
   const ready=candidates.filter(c=>typeof c.foodId==="string"&&c.foodId.length>0&&typeof c.grams==="number"&&Number.isFinite(c.grams)&&c.grams>0&&c.grams<=10000);
   if(!ready.length){
    throw new Error("Gemini could not produce a usable food estimate for this entry. Check the Gemini connection in Settings and try again.");
   }
   const items:MealSubmissionItem[]=ready.map(c=>({
    foodId:String(c.foodId),grams:Number(c.grams),
    portionEstimated:Boolean(c.portionEstimated||c.portionSource==="estimated"||c.confidence!=="high"),
    portionAmount:typeof c.amount==="number"&&c.amount>0?c.amount:undefined,
    portionUnit:typeof c.unit==="string"&&c.unit?c.unit:undefined,
    portionSource:c.portionEstimated||c.portionSource==="estimated"||c.confidence!=="high"?"estimated":"explicit",
    preparation:String(c.preparation||"as described"),
    portionNote:String(c.portionNote||c.notes||"")
   }));
   const saved=await saveMeal(items,"text",description);
   if(saved)setMessage("Meal automatically saved. Portion sizes and AI-estimated nutrient values are approximate.");
  }catch(e){setError(e instanceof Error?e.message:"Meal analysis or save failed.");}
  finally{setBusy(false);setMealStatus("");}
 }
 async function undoSavedMeal(){if(!savedMealResult)return;setBusy(true);setError("");try{await api("/api/meals/"+encodeURIComponent(String(savedMealResult.id)),"DELETE");setSavedMealResult(null);setMessage("Meal removed; its saved nutrient contribution was undone.");await refresh();}catch(e){setError(e instanceof Error?e.message:"Could not undo the saved meal.");}finally{setBusy(false);}}
