 async function updateMealItem(mealId:string,item:Row){const g=Number(edits[item.id]??item.grams),foodId=editFoodIds[item.id]??String(item.foodId||"");if(!Number.isFinite(g)||g<=0){setError("Enter a positive portion in grams.");return;}if(!foodId){setError("Choose a catalog food before saving this item.");return;}try{await api("/api/meals/"+mealId,"PATCH",{itemId:item.id,grams:g,foodId});setMessage("Food identity/portion saved and nutrients recalculated.");await refresh();}catch(e){setError(e instanceof Error?e.message:"Update failed.");}}
