 async function addMeasure(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);const units:Record<string,string>={weight:"kg",height:"cm",water:"L",sleep:"h",exercise:"min"};try{await api("/api/measurements","POST",{kind,value:Number(measureValue),unit:units[kind],note:measureNote,localDate:date,recordedAt:new Date().toISOString()});setMeasureValue("");setMeasureNote("");setMessage("Measurement saved.");await refresh();}catch(x){setError(x instanceof Error?x.message:"Measurement save failed.");}finally{setBusy(false);}}
 async function addDailyNote(){
  const note=noteDraft.trim();if(!note)return;
  const signature=JSON.stringify({date,note});
  if(noteAttemptRef.current?.signature!==signature)noteAttemptRef.current={signature,key:crypto.randomUUID()};
  const idempotencyKey=noteAttemptRef.current.key;
  setBusy(true);setError("");
  try{await api("/api/notes","POST",{localDate:date,note,idempotencyKey});noteAttemptRef.current=null;setNoteDraft("");setMessage("Daily note saved.");await refresh();}
  catch(e){setError(e instanceof Error?e.message:"Could not save note. Retry the same note to avoid duplicates.");}
  finally{setBusy(false);}
}
async function editDailyNote(id:string,oldNote:string){
  const updated=window.prompt("Edit this daily note",oldNote);if(updated===null)return;
  if(!updated.trim()){setError("A note cannot be empty. Delete it instead if it is no longer needed.");return;}
  try{await api("/api/notes/"+id,"PATCH",{note:updated.trim()});setMessage("Daily note updated.");await refresh();}
  catch(e){setError(e instanceof Error?e.message:"Could not update note.");}
}
async function deleteDailyNote(id:string){
 if(!window.confirm("Delete this daily note?"))return;
 try{await api("/api/notes/"+id,"DELETE");setMessage("Daily note deleted.");await refresh();}
 catch(e){setError(e instanceof Error?e.message:"Could not delete note.");}
}
function addRecipeIngredient(){const amount=Number(recipeGrams);if(!recipeFoodId||!Number.isFinite(amount)||amount<=0||amount>10000){setError("Choose a food and enter a valid gram amount.");return;}setRecipeIngredients(items=>[...items,{foodId:recipeFoodId,grams:amount}]);setRecipeGrams("100");setError("");}
 function editRecipe(recipe:Row){setEditingRecipeId(String(recipe.id));setRecipeName(String(recipe.name));setRecipeDescription(String(recipe.description||""));setRecipeServings(String(recipe.servings));setRecipeIngredients((recipe.ingredients||[]).map((i:Row)=>({foodId:String(i.foodId),grams:Number(i.grams)})).filter((i:{foodId:string;grams:number})=>Boolean(i.foodId)));setView("Recipes");setMessage("Recipe loaded into the editor. Save changes when ready.");}
 async function saveRecipe(e:React.FormEvent<HTMLFormElement>){e.preventDefault();if(!recipeIngredients.length){setError("Add at least one ingredient.");return;}setBusy(true);setError("");try{const body={name:recipeName,description:recipeDescription,servings:Number(recipeServings),ingredients:recipeIngredients};await api(editingRecipeId?"/api/recipes/"+editingRecipeId:"/api/recipes",editingRecipeId?"PATCH":"POST",body);setMessage(editingRecipeId?"Recipe updated and nutrition recalculated.":"Recipe saved.");setEditingRecipeId(null);setRecipeName("");setRecipeDescription("");setRecipeServings("2");setRecipeIngredients([]);await refresh();}catch(e){setError(e instanceof Error?e.message:"Could not save recipe.");}finally{setBusy(false);}}
 async function deleteRecipe(id:string){if(!window.confirm("Delete this saved recipe?"))return;try{await api("/api/recipes/"+id,"DELETE");if(editingRecipeId===id){setEditingRecipeId(null);setRecipeIngredients([]);setRecipeName("");setRecipeDescription("");}setMessage("Recipe deleted.");await refresh();}catch(e){setError(e instanceof Error?e.message:"Could not delete recipe.");}}
 async function saveSettings(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);try{const p={displayName:String(profile.displayName||"My profile"),age:Number(profile.age),sex:profile.sex,heightCm:Number(profile.heightCm),weightKg:Number(profile.weightKg),dietPreference:profile.dietPreference,region:String(profile.region||"Indian home-cooked")};const t=defs.map(n=>({key:n.key,target:targetInputs[n.key]===""?null:Number(targetInputs[n.key])}));await api("/api/profile","PATCH",{profile:p,targets:t});setProvider(null);setMessage("Profile and custom targets saved.");await refresh();}catch(e){setError(e instanceof Error?e.message:"Settings save failed.");}finally{setBusy(false);}}
 async function askAssistant(e:React.FormEvent<HTMLFormElement>){e.preventDefault();if(!assistantQuestion.trim())return;setAssistantBusy(true);setError("");setAssistantAnswer(null);try{const answer=await api("/api/assistant","POST",{question:assistantQuestion,date});setAssistantAnswer(answer);}catch(x){setError(x instanceof Error?x.message:"Assistant request failed.");}finally{setAssistantBusy(false);}}
 async function testGemini(){setBusy(true);try{const r=await fetch("/api/provider-status",{method:"POST"}),p=await r.json();setProvider((old:Row)=>({...old,testMessage:p.message||p.error,testOk:Boolean(r.ok&&p.ok)}));if(!r.ok)throw new Error(p.error||"Gemini test failed.");setMessage("Gemini test request succeeded.");}catch(e){setError(e instanceof Error?e.message:"Gemini test failed.");}finally{setBusy(false);}}
 async function logout(){await fetch("/api/auth/logout",{method:"POST"});router.replace("/login");router.refresh();}
 async function restorePersonalData(){if(!restoreFile){setError("Choose a MyNutri AI JSON export first.");return;}if(restoreFile.size>12*1024*1024){setError("Restore file must be 12 MB or smaller.");return;}const confirmation=window.prompt("Restore runs only when the current personal log store is empty; it will restore profile settings and imported records. Type RESTORE MY NUTRI DATA to continue.");if(confirmation!=="RESTORE MY NUTRI DATA")return;setBusy(true);setError("");try{const payload=JSON.parse(await restoreFile.text());const result=await api("/api/restore","POST",{confirmation:"RESTORE_MY_NUTRI_DATA",payload});setMessage("Restore complete: "+result.restored.meals+" meal(s), "+result.restored.foodItems+" food item(s), "+result.restored.measurements+" measurement(s).");setRestoreFile(null);await refresh();}catch(e){setError(e instanceof Error?e.message:"Could not restore export.");}finally{setBusy(false);}}
 async function deletePersonalData(){const confirmation=window.prompt("This permanently deletes personal meal logs, measurements, notes and target history. Food catalog records remain. Type DELETE MY PERSONAL DATA to continue.");if(confirmation!=="DELETE MY PERSONAL DATA")return;setBusy(true);setError("");try{await api("/api/data","DELETE",{confirmation:"DELETE_MY_PERSONAL_DATA"});setMessage("Personal meal logs and measurements deleted. The general food catalog and owner login remain.");await refresh();}catch(e){setError(e instanceof Error?e.message:"Could not delete personal records.");}finally{setBusy(false);}}
 function selectPhoto(file:File|null){setPhoto(file);setPhotoPreview("");if(!file)return;const reader=new FileReader();reader.onload=()=>setPhotoPreview(typeof reader.result==="string"?reader.result:"");reader.onerror=()=>setPhotoPreview("");reader.readAsDataURL(file);}
 function mealList(){if(!meals.length)return <div className="empty-state"><div className="empty-icon"><Utensils/></div><strong>No food entry recorded</strong><p>This does not mean a meal was skipped. Add a confirmed entry when ready.</p><button className="text-button" onClick={()=>go("Log Food")}>Log your first food →</button></div>;
 return <div className="meal-list">{meals.map((m:Row)=><div className="meal-row" key={m.id}><div className="meal-icon"><Utensils size={16}/></div><div className="meal-main"><div className="meal-name"><select className="select-control" style={{display:"inline-block",width:"auto",maxWidth:155,padding:"4px 7px",fontSize:11}} aria-label="Meal category" value={m.mealType} onChange={e=>void updateMealType(String(m.id),e.target.value)}>{mealTypes.map(x=><option key={x}>{x}</option>)}</select> <span className="pill">{clock(m.loggedAt)}</span></div>{m.items.map((it:Row)=><div key={it.id} className="meal-food-line"><strong>{it.foodName}</strong> · {fmt(Number(it.grams),1)} g · {it.nutrients?.kcal===undefined?"Energy unavailable":fmt(it.nutrients.kcal)+" kcal"} {it.portionEstimated?<span className="pill warn">Estimated</span>:null}<div className="meal-meta">{it.source} · {it.confidence==="verified"?"Verified reference":it.confidence==="user"?"User entered":"Provisional estimate"}</div><div className="button-row" style={{marginTop:5,alignItems:"center"}}><select className="select-control" aria-label={"Correct food identity for "+it.foodName} style={{width:"min(100%,190px)",padding:"6px 8px",fontSize:11}} value={editFoodIds[it.id]??String(it.foodId||"")} onChange={e=>setEditFoodIds(o=>({...o,[it.id]:e.target.value}))}><option value="">Choose food…</option>{foods.map(f=><option key={f.id} value={f.id}>{f.name}</option>)}</select><input className="inline-grams" aria-label={"grams for "+it.foodName} type="number" min="1" max="10000" value={edits[it.id]??String(it.grams)} onChange={e=>setEdits(o=>({...o,[it.id]:e.target.value}))}/><button className="small-icon-button" title="Save food and portion" aria-label="Save food and portion" onClick={()=>void updateMealItem(m.id,it)}><Check size={13}/></button><button className="small-icon-button danger" title="Delete food item" aria-label={"Delete "+it.foodName} onClick={()=>void deleteMealItem(m.id,String(it.id),it.foodName)}><Trash2 size={13}/></button></div></div>)}{m.originalText?<div className="meal-meta">Original: {m.originalText}</div>:null}</div><button className="small-icon-button danger" title="Delete meal" onClick={()=>void deleteMeal(m.id)}><Trash2 size={14}/></button></div>)}</div>;}
 function notesPanel(){
 return <section className="panel" style={{marginTop:14,marginBottom:14}}>
  <div className="panel-header"><div><h3 className="panel-title">Daily notes</h3><p className="panel-subtitle">Private notes saved against {dayLabel(date)}. Only explicitly recorded context appears here.</p></div><BookOpen size={17}/></div>
  <form onSubmit={e=>{e.preventDefault();void addDailyNote();}}>
   <div className="form-field"><label htmlFor="daily-note-draft">Add a note</label><textarea id="daily-note-draft" className="textarea-control" style={{minHeight:70}} maxLength={4000} value={noteDraft} onChange={e=>setNoteDraft(e.target.value)} placeholder="Optional meal context, measurement conditions or a reminder…"/></div>
   <div className="button-row" style={{marginTop:9}}><button className="primary-button" type="submit" disabled={busy||!noteDraft.trim()}><Plus size={15}/> Save note for this date</button><span className="panel-subtitle">{noteDraft.length}/4000 characters</span></div>
  </form>
  <div className="recommendation-list" style={{marginTop:13}}>
   {notes.length?notes.map((note:Row)=><div className="food-card" key={note.id}><div style={{minWidth:0,flex:1}}><p style={{margin:0,whiteSpace:"pre-wrap",overflowWrap:"anywhere"}}>{note.note}</p><p>Saved: {String(note.updated_at||note.created_at||"time unavailable").replace("T"," ").slice(0,19)}</p></div><div className="button-row"><button className="secondary-button" onClick={()=>void editDailyNote(String(note.id),String(note.note))}>Edit</button><button className="small-icon-button danger" aria-label="Delete daily note" title="Delete note" onClick={()=>void deleteDailyNote(String(note.id))}><Trash2 size={14}/></button></div></div>)
   :<div className="empty-state"><strong>No daily notes recorded</strong><p>Notes are optional and are never inferred from missing food entries.</p></div>}
  </div>
 </section>;
}
 const topKeys=["protein_g","carbs_g","fat_g","omega3_g","omega6_g","calcium_mg","iron_mg","magnesium_mg","vit_c_mg","vit_b12_ug"];
 const reportDays=(trendData?.days||[]) as Row[];
